function controls(){modal(`<small>FIELD GUIDE / 01</small><h2>Leave no footsteps.</h2><p>Find a fuse in the west guest villa, restore power in the utility yard by the helipad, then open the villa lockbox. Pick up fuel in the southeast boathouse and return to the boat on the north dock.</p><div class="controls"><span><b>W A S D</b> Move</span><span><b>MOUSE / ← →</b> Look</span><span><b>SHIFT</b> Sprint</span><span><b>C</b> Toggle crouch</span><span><b>E</b> Interact / hide / leave</span><span><b>Q</b> Close open wardrobe</span><span><b>F</b> Flashlight</span><span><b>M</b> Island map</span><span><b>Y / TAB</b> Backpack</span><span><b>J</b> Collected files</span><span><b>1 / 2 / 3 / 4</b> Bottle / bandage / cell / candle</span><span><b>8</b> Hitbox outline</span><span><b>9</b> Daylight test</span><span><b>ESC / P</b> Pause</span></div><p>Epstein sees your flashlight from across open ground. After exhausting stamina, recovery waits two seconds. Release Shift and catch your breath before sprinting again. With it off, the world is completely black and he cannot see you — but he still hears sprinting and searches your last position. Walls block his sight. The fictional Hawking and Trump apparitions hear ordinary footsteps from far away; crouch to move quietly. The Diddy apparition stalks before it begins hunting. Physical contact with any solid NPC is always lethal, even during its grace period. Not every footstep has a body. All character encounters are fictional nightmare scenarios. Open wardrobes with E, then press E again to step inside and close the door. Your flashlight switches off. E leaves; Q closes a wardrobe without entering. Hunters who see you enter can force the door. Drawers and house doors open and close. Search beds and desks, touch mirrors, check windows and inspect outdoor equipment. Bloody warnings and fresh hunter tracks can help you read the danger. Follow the real staircases to explore upper floors. Press Y or TAB to inspect and use carried items, or J to reread every collected file. Batteries power your flashlight; a candle and match provide short backup light. Crowbars, cutters and keys open optional supply cases. Throw bottles or place the recorder to lure listeners away. Crouch over glass and bandage cuts. The map, backpack and document reader pause the game. On touchscreens, drag the scene to look and use the screen controls.</p><button class="primary" id="closePanel">${hasStarted?'BACK TO THE ISLAND':'UNDERSTOOD'} <span>↗</span></button>`);$('#closePanel').onclick=()=>{if(hasStarted)resume();else{$('#overlay').hidden=true;paused=false;}};}
$('#how').onclick=controls;
function start(withIntro=false){if(mp?.id)mp.leave();reset();hasStarted=true;mode='game';paused=false;$('#menu').hidden=true;$('#side').hidden=true;$('#hud').hidden=false;$('#overlay').hidden=true;document.body.classList.add('playing');document.body.classList.remove('lights-off');$('#quickbar').hidden=false;initAudio();if(muted&&!soundChosen)soundToggle(false);updateHUD();toast('The landing is clear. Find the marked supplies. Do not trust every footstep. [M] Map.',6);if(matchMedia('(pointer:fine)').matches)lockPointer();last=performance.now();if(withIntro===true){mode='intro';$('#hud').hidden=true;$('#quickbar').hidden=true;if(document.pointerLockElement)document.exitPointerLock();arrival.start(p);}}
$('#start').onclick=()=>start(true);
function finishArrival(){arrival.stop();mode='game';paused=false;$('#hud').hidden=false;$('#quickbar').hidden=false;updateHUD();renderDirty=true;last=performance.now();lockPointer();}
$('#skipArrival').onclick=finishArrival;$('#loadSave').onclick=()=>saveModal();
$('#mapButton').onclick=()=>{if(mode==='game'&&!paused)mapModal();};$('#lightButton').onclick=()=>{if(mode==='game'&&!paused)toggleLight();};$('#inventoryButton').onclick=()=>inventoryModal();$('#filesButton').onclick=()=>inventoryModal('files');$('#pauseButton').onclick=pause;
function pause(){if(mode!=='game'||paused)return;if(mp?.active){coopPause();return;}modal(`<small>HOLD YOUR BREATH</small><h2>Still here.</h2><p>Your time: ${formatTime(elapsed)}. The island waits.</p><label class="volume-control" for="pauseVolume">MASTER VOLUME <output id="pauseVolumeValue">${Math.round(volume*100)}%</output><input id="pauseVolume" type="range" min="0" max="100" value="${Math.round(volume*100)}" step="1"></label><button class="primary" id="resume">KEEP GOING <span>↗</span></button><button class="secondary" id="guide">How to survive</button><button class="secondary" id="saveGame">Save / load code</button><button class="secondary" id="restart">Restart from the shore</button><button class="secondary" id="mainMenu">Main menu</button>`);$('#pauseVolume').oninput=e=>setVolume(e.target.value);$('#resume').onclick=resume;$('#guide').onclick=controls;$('#saveGame').onclick=()=>saveModal();$('#restart').onclick=start;$('#mainMenu').onclick=returnToMenu;}
function returnToMenu(){if(mp?.active)mp.leave();coopActor=null;arrival.stop();terror.clear();backpack.close();scares.clear();mode='menu';paused=false;hasStarted=false;debug.daylight=false;debug.hitbox=false;Object.keys(keys).forEach(k=>delete keys[k]);$('#menu').hidden=false;$('#side').hidden=false;$('#hud').hidden=true;$('#quickbar').hidden=true;$('#overlay').hidden=true;document.body.classList.remove('playing','danger','lights-off');if(document.pointerLockElement)document.exitPointerLock();renderDirty=true;}
function mapModal(){modal(`<small>ISLAND FIELD MAP / 1 UNIT = 1 METRE</small><h2>Find your way out.</h2><div class="map-tools"><button id="zoomOut">−</button><button id="zoomIn">+</button><button id="mapMe">FIND ME</button><button id="mapOverview">WHOLE ISLAND</button><span>Drag to pan · scroll to zoom</span></div><div class="pin-tools"><label>LABEL<input id="pinLabel" maxlength="48" value="Something here"></label><label>TYPE<select id="pinType"><option value="note">Note</option><option value="danger">Danger</option><option value="supply">Supplies</option><option value="hide">Hiding place</option></select></label><button id="pinMode" aria-pressed="false">ADD MARK</button><button id="pinUpdate">UPDATE MARK</button></div><p id="pinStatus">Drag to pan. Click Add mark to annotate.</p><div id="pinList" aria-label="Personal map marks"></div><canvas class="map large-map" id="mapCanvas" width="1000" height="850" aria-label="Island map with objectives and mapped buildings"></canvas><p class="legend">● YOU · 1 FUSE · 2 GENERATOR · 3 KEY · 4 FUEL · 5 ESCAPE · 6 OPTIONAL RECORDS<br>A compact fictional island: villa lanes, utility yard, wooded shortcuts and the north dock.<br><a href="compact-map.json" download>Download island layout</a></p><button class="primary" id="closeMap">BACK TO THE ISLAND <span>↗</span></button>`);$('#panel').classList.add('map-panel');let map=$('#mapCanvas'),c=map.getContext('2d'),zoom=1,cx=world.data.width/2,cz=world.data.depth/2,drag=null;function draw(){let scale=Math.min(940/world.data.width,790/world.data.depth)*zoom,xy=([x,z])=>[(x-cx)*scale+500,(z-cz)*scale+425];c.fillStyle='#071d25';c.fillRect(0,0,1000,850);c.strokeStyle='#31515933';c.lineWidth=1;for(let i=0;i<1000;i+=50){c.beginPath();c.moveTo(i,0);c.lineTo(i,850);c.stroke();}function poly(points,fill,stroke){c.beginPath();points.forEach((p,i)=>{let [x,y]=xy(p);i?c.lineTo(x,y):c.moveTo(x,y);});c.closePath();if(fill){c.fillStyle=fill;c.fill();}if(stroke){c.strokeStyle=stroke;c.stroke();}}poly(world.data.shore,'#283f2b','#9aa679');for(let road of world.roads){c.beginPath();road.points.forEach((p,i)=>{let [x,y]=xy(p);i?c.lineTo(x,y):c.moveTo(x,y);});c.strokeStyle='#a2a079';c.lineWidth=(road.tags.highway==='service'?2:1)*Math.min(zoom,2);c.stroke();}for(let building of world.buildings)poly(building.points,'#8f9b85','#b9c4a3');for(let f of world.data.features.filter(f=>f.tags.leisure==='swimming_pool'))poly(f.points,'#4a9aa2');world.landmarks.forEach(l=>{let [x,y]=xy([l.x,l.y]);c.font='10px monospace';c.fillStyle='#c8d1b5';c.fillText(l.name,x+8,y-9);});items.filter(o=>['fuse','generator','key','fuel','boat','evidence'].includes(o.id)).forEach(o=>{let [x,y]=xy([o.x,o.y]),row=objectiveRows().find(r=>r.id===o.id),index=['fuse','generator','key','fuel','boat','evidence'].indexOf(o.id)+1;c.fillStyle=row?.done?'#627c66':o.id===activeObjective().id?'#e6ed99':'#b8bf90';c.fillRect(x-6,y-6,12,12);c.font='bold 13px monospace';c.fillText(index,x+9,y+5);});if(mp?.active)for(const q of mp.players){let [tx,tz]=xy([q.x,q.y]);c.fillStyle=['#5bbaa0','#c9934d','#6c91cf','#d28a9c'][q.slot];c.beginPath();c.arc(tx,tz,5,0,7);c.fill();c.font='10px monospace';c.fillText((mp.lobby?.players.find(m=>m.id===q.id)?.name||'Survivor')+(q.status==='captured'?' [CAUGHT]':''),tx+9,tz+4);}mapPins.draw(c,xy);let [px,py]=xy([p.x,p.y]);c.fillStyle='#fff';c.beginPath();c.arc(px,py,5,0,7);c.fill();c.strokeStyle='#fff';c.lineWidth=2;c.beginPath();c.moveTo(px,py);c.lineTo(px+Math.cos(p.a)*15,py+Math.sin(p.a)*15);c.stroke();c.fillStyle='#e4e7d5';c.font='12px monospace';c.fillText('N ↑',35,30);c.fillRect(35,808,50*scale,3);c.fillText('50 m',35,799);c.fillText(world.stats.width+' × '+world.stats.depth+' m COMPACT ISLAND',600,825);}$('#zoomIn').onclick=()=>{zoom=Math.min(6,zoom*1.5);draw();};$('#zoomOut').onclick=()=>{zoom=Math.max(.7,zoom/1.5);draw();};$('#mapMe').onclick=()=>{cx=p.x;cz=p.y;zoom=Math.max(2,zoom);draw();};$('#mapOverview').onclick=()=>{cx=world.data.width/2;cz=world.data.depth/2;zoom=1;draw();};map.addEventListener('wheel',e=>{e.preventDefault();zoom=Math.max(.7,Math.min(6,zoom*(e.deltaY<0?1.15:.87)));draw();},{passive:false});map.addEventListener('pointerdown',e=>{if(mapPins.mode!=='pan')return;drag={x:e.clientX,y:e.clientY};map.setPointerCapture(e.pointerId);});map.addEventListener('pointermove',e=>{if(!drag)return;let rect=map.getBoundingClientRect(),scale=Math.min(940/world.data.width,790/world.data.depth)*zoom;cx-=(e.clientX-drag.x)*1000/rect.width/scale;cz-=(e.clientY-drag.y)*850/rect.height/scale;drag={x:e.clientX,y:e.clientY};draw();});map.addEventListener('pointerup',()=>drag=null);mapPins.attach(map,()=>({scale:Math.min(940/world.data.width,790/world.data.depth)*zoom,cx,cz}),draw);draw();$('#closeMap').onclick=resume;}
function gameCamera(){const motion=!paused&&!immersion.hidden&&!matchMedia('(prefers-reduced-motion: reduce)').matches?motionAmount:0,bob=Math.sin(motionPhase)*(actualRunning?.072:crouch?.012:.027)*motion,sway=Math.sin(motionPhase*.5)*(actualRunning?.034:.012)*motion;return{...p,x:p.x-Math.sin(p.a)*sway,y:p.y+Math.cos(p.a)*sway,pitch:p.pitch+Math.cos(motionPhase*.5)*(actualRunning?.013:.004)*motion,height:(p.feet??world.heightAt(p.x,p.y))+(crouch&&!immersion.hidden?1:1.62)+bob};}
function refreshFocus(){const selected=flashlight||backpack.light||debug.daylight||immersion.hidden?S.select(gameCamera(),p):null;closest=selected?.object||null;return closest;}
function interact(){if(mode!=='game'||paused)return;if(mp?.active){mp.action('interact',coopAim());return;}refreshFocus();if(closest)interactTarget(closest);}
function interactTarget(o=closest){if(mode!=='game'||paused||!o||o.taken)return;closest=o;if(backpack.handle(o,survivalContext()))return;if(o.sceneObject){immersion.interact(o,roomContext());updateHUD();return;}playerNoise(o.id==='generator'?110:14);if(o.story){backpack.archiveDoc(o.id,{title:o.story[0],author:'FICTIONAL EXPLORER JOURNAL',location:o.location,text:[o.story[1]]});o.taken=true;horror.recordJournal();modal('<small>FICTIONAL EXPLORER JOURNAL / '+horror.journalCount+' OF 10</small><h2>'+o.story[0]+'</h2><p>'+o.story[1]+'</p><button class="primary" id="storyClose">PUT IT AWAY <span>↗</span></button>');$('#storyClose').onclick=resume;updateHUD();return;}if(o.id==='fuse'){backpack.add('fuse');inv.fuse=true;o.taken=true;tone(660,.3);toast('Fuse recovered. The generator is beside the central helipad.');}if(o.id==='generator'){if(!inv.fuse&&!inv.power){toast('The fuse slot is empty. Search the west guest villa.');return;}if(inv.power){toast('The generator is running. The villa lockbox has power.');return;}inv.power=true;inv.fuse=false;backpack.remove('fuse');tone(65,2,.15,'sawtooth',100);toast('Power restored. The villa’s electronic lockbox is active.',5);guard.state='search';guard.lastX=p.x;guard.lastY=p.y;guard.search=10;}
if(o.id==='key'){if(!inv.power){toast('The lockbox has no power. Restore the generator first.');return;}backpack.add('key');inv.key=true;o.taken=true;tone(880,.4);toast('Boat key recovered. Find fuel in the southeast boathouse.');}
if(o.id==='fuel'){backpack.add('fuel');inv.fuel=true;o.taken=true;tone(440,.3);toast(inv.key?'Fuel recovered. Get back to the north dock.':'Fuel recovered. You still need the boat key from the villa.');}
if(o.id==='boat'){if(!inv.key||!inv.fuel){toast('The boat needs '+[!inv.key?'its key':null,!inv.fuel?'fuel':null].filter(Boolean).join(' and ')+'.');return;}finish(true);}
if(o.id==='note'){backpack.archiveDoc('dock-manifest');modal(`<small>MAINTENANCE LOG / 00:43</small><h2>The lights went out.</h2><p>“Spare fuse is here in the maintenance hut. Generator is beside the central helipad. Once power is back, the key safe in the main villa should open.”</p><p>“Fuel cans are in the southeast boathouse. One last thing: Epstein can see the flashlight. Switch it off before he closes in. The dark hides you, but he remembers where you were. Move quietly.”</p><button class="primary" id="noteClose">PUT IT DOWN <span>↗</span></button>`);$('#noteClose').onclick=resume;}
if(o.id==='evidence'){backpack.add('evidence');backpack.archiveDoc('sealed-records');evidence=true;o.taken=true;tone(900,.3);toast('Sealed records secured. Bring them off the island.',5);}updateHUD();}
function capture(who=guard){if(mode!=='game')return;captor=who;captor.state='chase';mode='caught';caughtAt=time;captor.facing=Math.atan2(p.y-who.y,p.x-who.x);terror.capture(who.kind||'epstein',time);scareSound(1);try{scares.trigger('death',{kind:who.kind||'epstein',silent:true},time);}catch(error){console.warn('Capture presentation: '+error.message);}Object.keys(keys).forEach(k=>delete keys[k]);$('#prompt').style.display='none';$('#toast').textContent='';if(document.pointerLockElement)document.exitPointerLock();}
function finish(won,reason=null){mode=won?'won':'dead';paused=true;let record=won&&(!best||elapsed<best);if(record){best=elapsed;try{localStorage.setItem('no-return-best',best);}catch{}}tone(won?220:70,won?2:1.2,.2,won?'sine':'sawtooth',won?440:25);modal(`<small>${won?'TRANSMISSION RESTORED / DAWN APPROACHING':'TRANSMISSION TERMINATED'}</small><h2>${won?'You made it out.':'You were found.'}</h2><p>${won?'The engine catches. The dock disappears into the dark. A covered shape on the shore grows smaller. For the first time tonight, the footsteps stop.':(reason||'A hand catches your shoulder. The last thing you hear is the ocean. You were so close to leaving.')}</p><p>${won?`ESCAPE TIME ${formatTime(elapsed)} · ${record?'NEW PERSONAL BEST':'BEST '+formatTime(best)}<br>${evidence?'You brought the sealed records with you. Some secrets won’t stay on this island.':'You escaped. The sealed records remain in the hilltop pavilion.'}`:'Break line of sight behind walls. Turn off your light and crouch when Epstein is close. Sprint only when you need distance.'}</p><button class="primary" id="again">${won?'RETURN TO THE ISLAND':'TRY AGAIN'} <span>↗</span></button><button class="secondary" id="endMap">Study the island map</button>`);$('#again').onclick=start;$('#endMap').onclick=()=>{mapModal();$('#closeMap').onclick=()=>finish(won);};document.body.classList.remove('danger');}
function contactCapture(previousPlayer=null,origins=null){if(mode!=='game')return false;for(let e of [guard,...horror.enemies])if(window.ISLAND_CONTACT.touching(world,e,p,{fromPlayer:previousPlayer,fromEnemy:origins?.get(e),crouching:crouch})){capture(e);return true;}return false;}
function update(dt){if(mp?.active){updateCoop(dt);return;}const previousPlayer=window.ISLAND_CONTACT.snapshot(world,p),origins=new Map([guard,...horror.enemies].map(e=>[e,window.ISLAND_CONTACT.snapshot(world,e)]));if(contactCapture())return;elapsed+=dt;let turning=(keys.ArrowRight?1:0)-(keys.ArrowLeft?1:0);p.a+=turning*dt*1.8;let f=(keys.w||keys.ArrowUp?1:0)-(keys.s||keys.ArrowDown?1:0),s=(keys.d?1:0)-(keys.a?1:0);if(immersion.hidden){f=0;s=0;}if(!keys.Shift)sprintReleased=true;if(exhausted&&recoveryDelay<=0&&sprintReleased&&stamina>=20)exhausted=false;const running=!!keys.Shift&&!exhausted&&stamina>0&&!crouch&&(f||s),speed=(crouch?1.45:running?6.4:3.4)*backpack.speedFactor;if(f||s){let len=Math.hypot(f,s);move(p,(Math.cos(p.a)*f-Math.sin(p.a)*s)/len*speed*dt,(Math.sin(p.a)*f+Math.cos(p.a)*s)/len*speed*dt);}actualMoving=Math.hypot(p.x-previousPlayer.x,p.y-previousPlayer.y)>.001;actualRunning=!!running&&actualMoving;if(actualMoving){steps+=Math.hypot(p.x-previousPlayer.x,p.y-previousPlayer.y);if(steps>(actualRunning?1.55:1.35)){steps=0;tone(crouch?48:actualRunning?92:72,.17,crouch?.025:actualRunning?.23:.13,'triangle',32);if(!crouch)rustle(p.x,p.y,.11);}}motionPhase+=dt*(actualRunning?15:9);motionAmount+=(actualMoving?1-motionAmount:-motionAmount)*Math.min(1,dt*10);if(actualRunning){stamina=Math.max(0,stamina-18*dt);if(stamina<=0){recoveryDelay=2;exhausted=true;sprintReleased=false;actualRunning=false;}}else if(recoveryDelay>0){let recover=Math.max(0,dt-recoveryDelay);recoveryDelay=Math.max(0,recoveryDelay-dt);stamina=Math.min(100,stamina+14*recover);}else stamina=Math.min(100,stamina+14*dt);breathing(dt,actualRunning);backpack.update(dt,survivalContext());if(mode!=='game')return;immersion.update(dt,roomContext());constrainHideLook();
if(contactCapture(previousPlayer,origins))return;
const aiContext={p,previousPlayer,elapsed,enemies:[guard,...horror.enemies],lightMode:flashlight?'flashlight':backpack.light?'candle':'none',flashlight:flashlight||backpack.light,crouch,running:actualRunning,moving:actualMoving,noise:lastNoise,move,capture,sound:soundAt,rustle,scare:(kind,meta)=>scares.trigger(kind,meta,time)};
V.prepare(aiContext);const perception=npcBrain.tick(guard,aiContext,dt),gd=Math.hypot(p.x-guard.x,p.y-guard.y);
if(perception.seen&&perception.changed){tone(51,.8,.16,'sawtooth',27);toast('He saw the light. Break sight, switch it off, and move quietly. [F]',3);}alert=perception.seen?Math.min(1,alert+dt*1.5):Math.max(0,alert-dt*.2);
if(contactCapture(previousPlayer,origins))return;
if(gd<22&&Math.hypot(guard.x-origins.get(guard).x,guard.y-origins.get(guard).y)>.001){enemyStep+=dt;if(enemyStep>(guard.state==='chase'?.36:.66)){enemyStep=0;soundAt(72,.18,.28*Math.max(0,1-gd/24),'triangle',35,guard.x,guard.y);}}
horror.update(dt,aiContext);if(mode!=='game'||contactCapture(previousPlayer,origins))return;refreshFocus();$('#prompt').style.display=closest?'block':'none';if(closest)$('#prompt').textContent=closest.hint;if(time>toastUntil)$('#toast').textContent='';if(Math.random()<dt*.018)tone(38,2,.17,'sawtooth',20);updateHUD();}
function render(){if(!renderer)return;let menu=mode==='menu'||mode==='intro'&&!arrival.lightOn,caught=mode==='caught',who=captor||guard;let motion=!paused&&!immersion.hidden&&!matchMedia('(prefers-reduced-motion: reduce)').matches?motionAmount:0;let bob=Math.sin(motionPhase)*(actualRunning?.072:crouch?.012:.027)*motion,sway=Math.sin(motionPhase*.5)*(actualRunning?.034:.012)*motion;let camera=arrival.active?arrival.camera():menu?{x:world.start.x,y:world.start.y,a:(world.data.layout?.startAngle??Math.PI*.22)+Math.sin(time*.13)*.18,pitch:-.06,height:world.heightAt(world.start.x,world.start.y)+1.65}:caught&&!window.ISLAND_COMFORT?.plain&&window.ISLAND_COMFORT?.jumpscares!==false?{x:who.x+Math.cos(who.facing)*.62,y:who.y+Math.sin(who.facing)*.62,a:who.facing+Math.PI,pitch:.01,height:(who.feet??world.heightAt(who.x,who.y))+(who.kind==='hawking'?1.31:1.72)}:gameCamera();const outline=window.ISLAND_OUTLINE.model(mode==='game'&&!paused?closest:null,flashlight||backpack.light||debug.daylight);renderer.render({camera,outline,introParts:arrival.active?arrival.parts(camera):null,enemy:guard,time:elapsed,weatherTime:time,menu,flashlight:menu||caught||flashlight||backpack.light,candle:!flashlight&&backpack.light,daylight:debug.daylight,hitbox:debug.hitbox,enemies:horror.enemies,players:mp?.active?mp.players:[],illusions:horror.illusions,focus:closest?.id,player:p});}
function frame(now){if(document.hidden){last=now;requestAnimationFrame(frame);return;}const dt=Math.min(.05,(now-last)/1000||.016);last=now;time+=dt;if(mode==='intro')arrival.update(dt,{sound:soundAt,rustle,finish:finishArrival});scares.update(time,mode==='game'&&!paused?{p,flashlight}:null);if(mp?.active){mp.frame(dt,coopInput());if(paused&&mode==='game')renderDirty=true;}if(mode==='game'&&!paused)update(dt);terror.update(time,{active:mode==='game'&&!paused,lit:flashlight||backpack.light||debug.daylight,hidden:!!p.hidden,p,enemies:[guard,...horror.enemies]});if(mode==='caught'&&time-caughtAt>.9)finish(false);if(!paused&&(mode==='game'||mode==='intro')||mode==='caught'||renderDirty||now-lastRenderAt>(mode==='menu'?250:1000)){try{render();renderDirty=false;lastRenderAt=now;}catch(error){graphicsFailure(error);renderDirty=false;}}requestAnimationFrame(frame);}
requestAnimationFrame(frame);
addEventListener('keydown',e=>{if(/^(INPUT|TEXTAREA|SELECT)$/.test(e.target?.tagName))return;if(renderError)return;if(mode==='intro'){if(e.key==='Escape'||e.key===' ')finishArrival();return;}if(e.key==='Tab'&&backpack.opened)return;if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight',' ','Tab'].includes(e.key))e.preventDefault();let k=e.key.length===1?e.key.toLowerCase():e.key;if(e.repeat){if(!paused)keys[k]=true;return;}if(k==='8'){debug.hitbox=!debug.hitbox;updateHUD();return;}if(k==='9'){debug.daylight=!debug.daylight;updateHUD();return;}if((k==='y'||k==='Tab'||k==='j')&&mode==='game'){if(backpack.opened)resume();else inventoryModal(k==='j'?'files':'gear');return;}if(k==='Escape'||k==='p'){if(paused&&mode==='game')resume();else pause();return;}if(paused){if(k==='m'&&mode==='game')resume();return;}keys[k]=true;if(mode==='game'&&['1','2','3','4'].includes(k))quickUse({'1':'bottle','2':'bandage','3':'battery','4':'candle'}[k]);if(k==='e')interact();if(k==='q')refreshFocus();if(k==='q'&&!immersion.hidden&&closest?.kind==='closet'){if(mp?.active)mp.action('close',coopAim());else immersion.interact(closest,roomContext(),true);updateHUD();}if(k==='c'&&!immersion.hidden){crouch=!crouch;updateHUD();}if(k==='t'&&mp?.active){mp.trade();return;}if(k==='f')toggleLight();if(k==='m'&&mode==='game')mapModal();});
addEventListener('keyup',e=>{delete keys[e.key.length===1?e.key.toLowerCase():e.key];if(e.key==='Shift')sprintReleased=true;});
addEventListener('blur',()=>{Object.keys(keys).forEach(k=>delete keys[k]);if(mode==='game'&&!paused)pause();});
