function snapshotGame(){return JSON.parse(JSON.stringify({player:{...p},guard,inventory:{...inv},stamina,recoveryDelay,exhausted,sprintReleased,elapsed,time,flashlight,crouch,evidence,steps,lastNoise,items:items.map(o=>({id:o.id,taken:!!o.taken,open:!!o.open})),backpack:backpack.snapshot(),rooms:immersion.snapshot(),horror:horror.snapshot(),scares:scares.snapshot(),markers:mapPins.snapshot}));}
function applyGameState(s){start(false);Object.assign(p,s.player);guard=s.guard;inv={...s.inventory};stamina=s.stamina;recoveryDelay=s.recoveryDelay;exhausted=s.exhausted;sprintReleased=s.sprintReleased;elapsed=s.elapsed;time=s.time;flashlight=s.flashlight;crouch=s.crouch;evidence=s.evidence;steps=s.steps||0;lastNoise=s.lastNoise;horror.restore(s.horror);backpack.restore(s.backpack);for(let i=0;i<items.length;i++){Object.assign(items[i],{taken:s.items[i].taken,open:s.items[i].open});items[i].meshVersion=(items[i].meshVersion||0)+1;}immersion.restore(s.rooms,[guard,...horror.enemies]);scares.restore(s.scares);mapPins.restore(s.markers);actualMoving=false;actualRunning=false;motionAmount=0;Object.keys(keys).forEach(k=>delete keys[k]);mode='game';paused=false;checklistCache='';$('#overlay').hidden=true;updateHUD();refreshFocus();renderDirty=true;last=performance.now();}
function loadGameCode(code){const s=window.ISLAND_SAVE_CODES.validate(window.ISLAND_SAVE_CODES.decode(code)),previous=hasStarted?snapshotGame():null;try{applyGameState(s);}catch(error){if(previous)applyGameState(previous);throw error;}toast('State restored. Your map marks and collected files are back.',5);return true;}
function saveModal(){if(mp?.active){toast('Save codes are for solo runs. Your co-op session reconnects for 90 seconds after a disconnect.');return;}const canSave=hasStarted&&mode==='game',code=canSave?window.ISLAND_SAVE_CODES.encode(snapshotGame()):'';modal('<small>FIELD RECOVERY / PORTABLE SAVE</small><h2>Leave a way back.</h2><p>A save code contains this run: your position, supplies, collected files, opened rooms, hunters and map marks. Keep the complete code to continue later.</p>'+(canSave?'<label class="save-label" for="saveOutput">YOUR CURRENT STATE</label><textarea id="saveOutput" class="save-code" rows="4" readonly spellcheck="false"></textarea><div class="save-actions"><button id="copySave">COPY CODE</button><button id="downloadSave">DOWNLOAD .TXT</button></div>':'')+'<label class="save-label" for="saveInput">RESTORE A CODE</label><textarea id="saveInput" class="save-code" rows="4" maxlength="160000" spellcheck="false" placeholder="Paste the complete NR1. code here"></textarea><p id="saveStatus" role="status"></p><button id="restoreSave" class="primary">RESTORE STATE <span>↗</span></button><button id="cancelSave" class="secondary">'+(canSave?'Back to this run':'Back to the menu')+'</button>');if(canSave){$('#saveOutput').value=code;$('#copySave').onclick=async()=>{try{await navigator.clipboard.writeText(code);$('#saveStatus').textContent='Code copied. Keep it somewhere safe.';}catch{$('#saveOutput').select?.();$('#saveStatus').textContent='Select the code above and copy it.';}};$('#downloadSave').onclick=()=>{const url=URL.createObjectURL(new Blob([code+'\n'],{type:'text/plain'})),link=document.createElement('a');link.href=url;link.download='no-return-save.txt';link.click();URL.revokeObjectURL(url);};}$('#restoreSave').onclick=()=>{try{loadGameCode($('#saveInput').value);}catch(error){$('#saveStatus').textContent=error.message;}};$('#cancelSave').onclick=canSave?resume:returnToMenu;}
