function coopInput(){const enabled=mp?.connected&&!paused&&mode==='game'&&coopActor?.status==='alive';return{a:p.a,pitch:p.pitch,f:enabled?(keys.w||keys.ArrowUp?1:0)-(keys.s||keys.ArrowDown?1:0):0,s:enabled?(keys.d?1:0)-(keys.a?1:0):0,sprint:enabled&&!!keys.Shift,crouch,rescue:enabled&&!!keys.r};}
