  if(snap)Object.assign(p,q.p);else{p.x+=(q.p.x-p.x)*.45;p.y+=(q.p.y-p.y)*.45;Object.assign(p,{feet:q.p.feet,level:q.p.level,building:q.p.building,hidden:q.p.hidden,closetId:q.p.closetId});}
  if(!snap)Object.assign(p,look);Object.assign(coopActor,{...q,p});stamina=q.stamina;recoveryDelay=q.recoveryDelay;exhausted=q.exhausted;flashlight=q.flashlight;elapsed=s.elapsed;inv={fuse:s.quest.fuse,power:s.quest.power,key:s.quest.key,fuel:s.quest.fuel};evidence=s.quest.evidence;
  const bagWasOpen=backpack.opened;backpack.restore(q.bag,true);guard={...s.enemies[0],path:[]};const h=horror.snapshot();h.enemies=s.enemies.slice(1).map(e=>({...e,path:[]}));h.illusions=s.illusions||[];h.journalCount=items.filter(o=>o.story&&q.bag.documents.includes(o.id)).length;horror.restore(h);
  for(const item of s.items||[]){const o=items.find(o=>o.id===item.id);if(o)Object.assign(o,item);}if(s.rooms)immersion.restore({...s.rooms,hidden:q.p.closetId},[guard,...horror.enemies]);else immersion.setHidden(q.p.closetId);
